import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.carrotsearch.hppc.LongObjectHashMap;
import com.uber.ussi.config.NamespaceConfig;
import com.uber.ussi.entity.meta.LongMeta;
import com.uber.ussi.entity.meta.MetaFilter;
import com.uber.ussi.entity.termsandvalues.LongTermsAndValues;
import com.uber.ussi.entity.termsandvalues.LongTermsAndValuesTestFactory;
import com.uber.ussi.searchablestructure.result.RowNumAndSimilarity;
import com.uber.ussi.searchablestructure.utils.metadata.MetadataFilteringStrategy;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

class IndexEdgeCasesTest {

  @Test
  void baseIndexDefaultsAreUsable() {
    TestIndex index = new TestIndex(config(Map.of()), longObjectMap(), null);

    assertTrue(index.isEmpty());
    assertEquals(5, index.getPostFilteringMaxResultsForTests(5, MetaFilter.empty()));

    index.close();
  }

  @Test
  void postFilteringMaxResultsReturnsZeroWhenNoRowsMatchMetadata() {
    TestIndex index =
        new TestIndex(
            config(Map.of()),
            longObjectMap(1, denseInternal(1f, 0f)),
            longObjectMap(1, longMeta("city", "sf")));

    int maxResults =
        index.getPostFilteringMaxResultsForTests(
            5, new MetaFilter(Map.of("city", List.of("missing"))));

    assertEquals(0, maxResults);
  }

  /** A strategy named by nothing at all leaves the default, and a name no strategy has is fatal. */
  @Test
  void resolvesTheMetadataFilteringStrategyFromItsParam() {
    for (String blank : new String[] {"", "   "}) {
      TestIndex index =
          new TestIndex(
              config(Map.of(Index.METADATA_FILTERING_STRATEGY, blank)),
              longObjectMap(),
              longObjectMap());

      assertEquals(MetadataFilteringStrategy.AUTO, index.getMetadataFilteringStrategyForTests());
      index.close();
    }

    IllegalArgumentException error =
        assertThrows(
            IllegalArgumentException.class,
            () ->
                new TestIndex(
                    config(Map.of(Index.METADATA_FILTERING_STRATEGY, "sideways")),
                    longObjectMap(),
                    longObjectMap()));

    assertTrue(error.getMessage().contains("sideways"), error.getMessage());
  }

  /** An absent filter is no filter, which is how a search that carries none is told apart. */
  @Test
  void treatsAnAbsentAndAnEmptyFilterAsNoFilter() {
    TestIndex index = new TestIndex(config(Map.of()), longObjectMap(), longObjectMap());

    assertFalse(index.hasMetadataFilterForTests(null));
    assertFalse(index.hasMetadataFilterForTests(MetaFilter.empty()));
    assertTrue(index.hasMetadataFilterForTests(new MetaFilter(Map.of("city", List.of("sf")))));
    index.close();
  }

  @Test
  void constructorRejectsInvalidPreFilteringRatioValues() {
    assertThrows(
        IllegalArgumentException.class,
        () ->
            new TestIndex(
                config(Map.of(Index.MAX_PRE_FILTERING_ROWS_RATIO, "not-a-double")),
                longObjectMap(),
                longObjectMap()));
    assertThrows(
        IllegalArgumentException.class,
        () ->
            new TestIndex(
                config(Map.of(Index.MAX_PRE_FILTERING_ROWS_RATIO, "-0.1")),
                longObjectMap(),
                longObjectMap()));
  }

  private static NamespaceConfig config(Map<String, String> indexParams) {
    return NamespaceConfig.builder()
        .minTermsAndValuesLength(0)
        .maxTermsAndValuesLength(2)
        .maxCacheSize(100)
        .cacheType("scan")
        .indexType("scan")
        .indexParams(indexParams)
        .comparatorType("l2")
        .comparatorNormalizerType("reciprocal")
        .maxNumSearchableStructures(3)
        .maxNumSimilarities(10)
        .build();
  }

  private static LongTermsAndValues denseInternal(float... values) {
    double uniValue = 0.0;
    for (float value : values) {
      uniValue += value * value;
    }
    return LongTermsAndValuesTestFactory.create(new long[0], values, uniValue);
  }

  private static LongMeta longMeta(String key, String value) {
    return new LongMeta(Map.of(key, value), /* requireLongKeysAndValues */ false);
  }

  private static final class TestIndex extends RowStoringIndex {

    private TestIndex(
        NamespaceConfig namespaceConfig,
        LongObjectHashMap<LongTermsAndValues> rows,
        LongObjectHashMap<LongMeta> metadata) {
      super(namespaceConfig, rows, metadata);
    }

    private int getPostFilteringMaxResultsForTests(int maxResults, MetaFilter metadataFilter) {
      return getPostFilteringMaxResults(maxResults, metadataFilter);
    }

    private MetadataFilteringStrategy getMetadataFilteringStrategyForTests() {
      return metadataFilteringStrategy;
    }

    private boolean hasMetadataFilterForTests(MetaFilter metadataFilter) {
      return hasMetadataFilter(metadataFilter);
    }

    @Override
    protected List<RowNumAndSimilarity> searchNearestNeighbors(
        int numResults, LongTermsAndValues record, MetaFilter metadataFilter, float minSimilarity) {
      return Collections.emptyList();
    }

    @Override
    protected List<RowNumAndSimilarity> searchSimilarRowNums(
        float minSimilarity, LongTermsAndValues record, MetaFilter metadataFilter) {
      return Collections.emptyList();
    }
  }
}

package com.uber.ussi.searchablestructure.index;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.uber.ussi.comparator.Comparator;
import com.uber.ussi.comparator.DotProductScored;
import com.uber.ussi.comparator.ComparatorFactory;
import com.uber.ussi.config.ConfigVocabulary;
import com.uber.ussi.config.NamespaceConfig;
import com.uber.ussi.entity.termsandvalues.RecordType;
import java.util.List;
import java.util.Set;
import org.junit.jupiter.api.Test;

class IndexTypeTest {

  @Test
  void paramValuesAreTheLowercasedNames() {
    assertEquals("scan", IndexType.SCAN.getParamValue());
    assertEquals("inverted_term", IndexType.INVERTED_TERM.getParamValue());
    assertEquals(IndexType.MATRIX, ConfigVocabulary.fromParamValue(IndexType.class, "matrix"));
    assertEquals(
        IndexType.INVERTED_HYBRID,
        ConfigVocabulary.fromParamValue(IndexType.class, " INVERTED_Hybrid "));
  }

  @Test
  void anUnknownParamValueHasNoIndexType() {
    assertNull(ConfigVocabulary.fromParamValue(IndexType.class, "hnsw"));
  }

  /**
   * An inverted structure stores either type that has terms, whether it keys its lists by those
   * terms or by signatures drawn from them.
   */
  @Test
  void storableRecordTypesAreTheTypesTheStructureKeeps() {
    assertEquals(Set.of(RecordType.DENSE), IndexType.MATRIX.getStorableRecordTypes());
    assertEquals(
        Set.of(RecordType.SPARSE, RecordType.SEQUENCE),
        IndexType.INVERTED_TERM.getStorableRecordTypes());
    assertEquals(
        Set.of(RecordType.SPARSE, RecordType.SEQUENCE),
        IndexType.INVERTED_SIGNATURE.getStorableRecordTypes());
    assertEquals(
        Set.of(RecordType.SPARSE, RecordType.SEQUENCE),
        IndexType.INVERTED_HYBRID.getStorableRecordTypes());
    assertEquals(
        Set.of(
            RecordType.DENSE, RecordType.SPARSE, RecordType.SEQUENCE),
        IndexType.SCAN.getStorableRecordTypes());
  }

  /** The stored type is the one the structure keeps and the comparator reads, leaving one. */
  @Test
  void resolvingRecordTypesLeavesOneTypePerStructureAndComparator() {
    Comparator l2 = comparator("l2", "reciprocal");
    Comparator jaccard = comparator("jaccard", "identity");
    Comparator ngld = comparator("ngld", "complement");

    assertEquals(
        Set.of(RecordType.DENSE), IndexType.MATRIX.resolveRecordTypes(l2));
    assertEquals(
        Set.of(RecordType.SPARSE), IndexType.INVERTED_TERM.resolveRecordTypes(l2));
    assertEquals(
        Set.of(RecordType.SPARSE),
        IndexType.INVERTED_TERM.resolveRecordTypes(jaccard));
    assertEquals(Set.of(RecordType.SEQUENCE), IndexType.INVERTED_TERM.resolveRecordTypes(ngld));
  }

  /**
   * A comparator reading nothing a structure keeps is a pairing with no record type at all. Only
   * the matrix structure leaves one now: it is the one that stores neither type having terms.
   */
  @Test
  void resolvingRecordTypesIsEmptyForAnImpossiblePairing() {
    assertEquals(Set.of(), IndexType.MATRIX.resolveRecordTypes(comparator("ngld", "complement")));
    assertEquals(Set.of(), IndexType.MATRIX.resolveRecordTypes(comparator("gld", "reciprocal")));
  }

  /** The scan structure never reads a record's type, so it never asks which type it holds. */
  @Test
  void resolvingRecordTypesIsAmbiguousOnlyWhereTheAnswerIsUnused() {
    assertEquals(
        Set.of(RecordType.DENSE, RecordType.SPARSE),
        IndexType.SCAN.resolveRecordTypes(comparator("l2", "reciprocal")));
    assertEquals(
        Set.of(RecordType.DENSE, RecordType.SPARSE),
        IndexType.SCAN.resolveRecordTypes(comparator("jaccard", "identity")));
  }

  /**
   * The matrix structure shares a record type with every order-agnostic comparator, so what keeps
   * it to some of them is the arithmetic they can supply rather than the type it stores.
   */
  @Test
  void onlyTheMatrixStructureScoresByDotProducts() {
    assertEquals(
        Set.of(RecordType.DENSE),
        IndexType.MATRIX.resolveRecordTypes(comparator("jaccard", "identity")));

    assertTrue(IndexType.MATRIX.doesScoreByDotProducts());
    assertFalse(IndexType.SCAN.doesScoreByDotProducts());
    assertFalse(IndexType.INVERTED_TERM.doesScoreByDotProducts());
    assertFalse(IndexType.INVERTED_SIGNATURE.doesScoreByDotProducts());
    assertFalse(IndexType.INVERTED_HYBRID.doesScoreByDotProducts());

    assertTrue(comparator("l2", "reciprocal") instanceof DotProductScored);
    assertFalse(comparator("jaccard", "identity") instanceof DotProductScored);
  }

  @Test
  void onlyTheInvertedStructuresKeepTheListsTheGeneratorsWalk() {
    assertTrue(IndexType.INVERTED_TERM.doesSupportCandidateGenerator());
    assertTrue(IndexType.INVERTED_SIGNATURE.doesSupportCandidateGenerator());
    assertTrue(IndexType.INVERTED_HYBRID.doesSupportCandidateGenerator());
    assertFalse(IndexType.SCAN.doesSupportCandidateGenerator());
    assertFalse(IndexType.MATRIX.doesSupportCandidateGenerator());
  }

  @Test
  void onlyTheSignatureKeyedStructuresNeedAGenerator() {
    assertTrue(IndexType.INVERTED_SIGNATURE.doesKeyBySignatures());
    assertTrue(IndexType.INVERTED_HYBRID.doesKeyBySignatures());
    assertFalse(IndexType.INVERTED_TERM.doesKeyBySignatures());
    assertFalse(IndexType.SCAN.doesKeyBySignatures());
  }

  /**
   * A conjunction is a similarity only when the lists carry a record's own values, so it needs a
   * term-keyed structure and a type whose terms determine its similarity.
   */
  @Test
  void onlyTermKeyedListsOverSparseRecordsDetermineSimilarity() {
    assertTrue(
        IndexType.INVERTED_TERM.doesConjunctionDetermineSimilarity(
            RecordType.SPARSE));
    assertFalse(IndexType.INVERTED_TERM.doesConjunctionDetermineSimilarity(RecordType.SEQUENCE));
    assertFalse(
        IndexType.INVERTED_SIGNATURE.doesConjunctionDetermineSimilarity(
            RecordType.SPARSE));
    assertFalse(
        IndexType.INVERTED_HYBRID.doesConjunctionDetermineSimilarity(
            RecordType.SPARSE));
  }

  /**
   * Scan scores every row through the comparator, so it is the exact fallback for anything another
   * structure can do. Widening a structure without widening scan would leave that pairing with no
   * structure that scores it exactly.
   */
  @Test
  void scanStoresAndReadsEveryPairingAnotherStructureDoes() {
    Set<RecordType> scanStores = IndexType.SCAN.getStorableRecordTypes();
    for (IndexType indexType : IndexType.values()) {
      assertTrue(
          scanStores.containsAll(indexType.getStorableRecordTypes()),
          indexType.getParamValue() + " stores a record type scan does not.");
    }

    for (Comparator comparator : everyComparator()) {
      Set<RecordType> scanReads = IndexType.SCAN.resolveRecordTypes(comparator);
      for (IndexType indexType : IndexType.values()) {
        assertTrue(
            scanReads.containsAll(indexType.resolveRecordTypes(comparator)),
            indexType.getParamValue() + " resolves a record type scan does not.");
      }
    }

    // Storing the type is only half of it: scan also imposes neither of the checks that would
    // reject a comparator the pairing otherwise allows.
    assertFalse(IndexType.SCAN.doesScoreByDotProducts());
    assertFalse(IndexType.SCAN.doesKeyBySignatures());
  }

  private static List<Comparator> everyComparator() {
    return List.of(
        comparator("l2", "reciprocal"),
        comparator("jaccard", "identity"),
        comparator("ruzicka", "identity"),
        comparator("gld", "reciprocal"),
        comparator("ngld", "complement"));
  }

  private static Comparator comparator(String comparatorType, String normalizerType) {
    return ComparatorFactory.createComparator(
        NamespaceConfig.builder()
            .minTermsAndValuesLength(0)
            .maxTermsAndValuesLength(2)
            .maxCacheSize(10)
            .cacheType("scan")
            .indexType("scan")
            .comparatorType(comparatorType)
            .comparatorNormalizerType(normalizerType)
            .maxNumSearchableStructures(3)
            .maxNumSimilarities(10)
            .build());
  }
}

