package com.uber.ussi.searchablestructure.result;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

class RowNumAndSimilarityTest {

  private static final float DELTA = 1e-6f;

  @Test
  void accessorsReturnConstructorValues() {
    RowNumAndSimilarity hit = new RowNumAndSimilarity(7, 0.5f);

    assertEquals(7, hit.getRowNum());
    assertEquals(0.5f, hit.getSimilarity(), DELTA);
  }

  @Test
  void equalsAndHashCodeUseRowNumAndSimilarity() {
    RowNumAndSimilarity first = new RowNumAndSimilarity(7, 0.5f);
    RowNumAndSimilarity second = new RowNumAndSimilarity(7, 0.5f);
    RowNumAndSimilarity different = new RowNumAndSimilarity(8, 0.5f);

    assertEquals(first, second);
    assertEquals(first, first);
    assertEquals(first.hashCode(), second.hashCode());
    assertNotEquals(first, different);
    assertNotEquals(first, "not-a-hit");
  }

  @Test
  void toStringIncludesFields() {
    assertTrue(new RowNumAndSimilarity(7, 0.5f).toString().contains("RowNumAndSimilarity{"));
  }

  @Test
  void nearestFirstComparatorSortsBySimilarityThenRowNum() {
    List<RowNumAndSimilarity> hits = new ArrayList<>();
    hits.add(new RowNumAndSimilarity(9, 0.5f));
    hits.add(new RowNumAndSimilarity(2, 0.5f));
    hits.add(new RowNumAndSimilarity(1, 0.9f));

    hits.sort(RowNumAndSimilarity.NEAREST_FIRST);

    assertEquals(List.of(1L, 2L, 9L), hits.stream().map(RowNumAndSimilarity::getRowNum).toList());
  }

  @Test
  void topResultsHeapOrderTreatsSmallerRowNumAsBetterTieBreaker() {
    List<RowNumAndSimilarity> hits = new ArrayList<>();
    hits.add(new RowNumAndSimilarity(2, 0.5f));
    hits.add(new RowNumAndSimilarity(9, 0.5f));
    hits.add(new RowNumAndSimilarity(1, 0.9f));

    hits.sort(RowNumAndSimilarity.TOP_RESULTS_HEAP_ORDER);

    assertEquals(List.of(9L, 2L, 1L), hits.stream().map(RowNumAndSimilarity::getRowNum).toList());
  }
}

package com.uber.ussi.searchablestructure.index;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.uber.ussi.comparator.ComparatorType;
import com.uber.ussi.config.NamespaceConfig;
import com.uber.ussi.config.NamespaceConfig.CandidateGeneratorType;
import com.uber.ussi.utils.ConfigKeys;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

class IndexConfigValidatorTest {

  private static final ValidationCase[] VALIDATION_CASES = {
    new ValidationCase("defaults", builder -> builder, true),
    new ValidationCase(
        "unparseable max fraction",
        builder -> builder.indexParams(Map.of(ConfigKeys.MAX_FRACTION_IDS_PER_TERM, "bad")),
        false),
    new ValidationCase(
        "max fraction at zero",
        builder -> builder.indexParams(Map.of(ConfigKeys.MAX_FRACTION_IDS_PER_TERM, "0")),
        false),
    new ValidationCase(
        "pre-filtering ratio above one",
        builder -> builder.indexParams(Map.of(Index.MAX_PRE_FILTERING_ROWS_RATIO, "1.5")),
        false),
    new ValidationCase(
        "unsupported metadata strategy",
        builder -> builder.indexParams(Map.of(Index.METADATA_FILTERING_STRATEGY, "guesswork")),
        false),
    new ValidationCase(
        "an index type that names no structure", builder -> builder.indexType("term"), false),
    new ValidationCase(
        "spars merge on the scan structure",
        builder ->
            builder
                .indexType(IndexType.SCAN.getParamValue())
                .indexParams(Map.of(ConfigKeys.CANDIDATE_GENERATOR, sparsMerge())),
        false),
    new ValidationCase(
        "spars merge with l2 on the signature structure",
        builder ->
            builder
                .indexType(IndexType.INVERTED_SIGNATURE.getParamValue())
                .comparatorType(ComparatorType.L2.getParamValue())
                .indexParams(Map.of(ConfigKeys.CANDIDATE_GENERATOR, sparsMerge())),
        false),
    new ValidationCase(
        "spars merge with l2 on the term structure",
        builder ->
            builder
                .indexType(IndexType.INVERTED_TERM.getParamValue())
                .comparatorType(ComparatorType.L2.getParamValue())
                .indexParams(Map.of(ConfigKeys.CANDIDATE_GENERATOR, sparsMerge())),
        true),
    new ValidationCase(
        "spars merge with ngld on the term structure",
        builder ->
            builder
                .indexType(IndexType.INVERTED_TERM.getParamValue())
                .comparatorType(ComparatorType.NGLD.getParamValue())
                .indexParams(Map.of(ConfigKeys.CANDIDATE_GENERATOR, sparsMerge())),
        true),
    new ValidationCase(
        "spars merge with gld on the term structure",
        builder ->
            builder
                .indexType(IndexType.INVERTED_TERM.getParamValue())
                .comparatorType(ComparatorType.GLD.getParamValue())
                .indexParams(Map.of(ConfigKeys.CANDIDATE_GENERATOR, sparsMerge())),
        true),
    new ValidationCase(
        "spars merge with gld on the hybrid structure",
        builder ->
            builder
                .indexType(IndexType.INVERTED_HYBRID.getParamValue())
                .comparatorType(ComparatorType.GLD.getParamValue())
                .indexParams(Map.of(ConfigKeys.CANDIDATE_GENERATOR, sparsMerge())),
        false),
    // Ruzicka scores a row from the keys it shares with the query, so merge stays available.
    new ValidationCase(
        "spars merge with ruzicka on the term structure",
        builder ->
            builder
                .indexType(IndexType.INVERTED_TERM.getParamValue())
                .comparatorType(ComparatorType.RUZICKA.getParamValue())
                .indexParams(Map.of(ConfigKeys.CANDIDATE_GENERATOR, sparsMerge())),
        true),
    // A sequence has no values, so only the term structure, which keys the term multiset, and
    // the scan structure, which never reads terms, can hold one.
    new ValidationCase(
        "ngld on the term structure",
        builder ->
            builder
                .indexType(IndexType.INVERTED_TERM.getParamValue())
                .comparatorType(ComparatorType.NGLD.getParamValue()),
        true),
    new ValidationCase(
        "gld on the scan structure",
        builder ->
            builder
                .indexType(IndexType.SCAN.getParamValue())
                .comparatorType(ComparatorType.GLD.getParamValue()),
        true),
    new ValidationCase(
        "ngld on the signature structure",
        builder ->
            builder
                .indexType(IndexType.INVERTED_SIGNATURE.getParamValue())
                .comparatorType(ComparatorType.NGLD.getParamValue()),
        false),
    // Discarding a popular term drops it from the sequences too, so the pairing stays valid.
    new ValidationCase(
        "the term structure discarding popular terms",
        builder ->
            builder
                .indexType(IndexType.INVERTED_TERM.getParamValue())
                .comparatorType(ComparatorType.NGLD.getParamValue())
                .indexParams(Map.of(ConfigKeys.MAX_FRACTION_IDS_PER_TERM, "0.05")),
        true),
    new ValidationCase(
        "the term structure keeping every term",
        builder ->
            builder
                .indexType(IndexType.INVERTED_TERM.getParamValue())
                .comparatorType(ComparatorType.NGLD.getParamValue())
                .indexParams(Map.of(ConfigKeys.MAX_FRACTION_IDS_PER_TERM, "1.0")),
        true),
    // L2 reads both dense and sparse records, so no structure here can turn it away.
    new ValidationCase(
        "l2 on the term structure",
        builder ->
            builder
                .indexType(IndexType.INVERTED_TERM.getParamValue())
                .comparatorType(ComparatorType.L2.getParamValue()),
        true),
    new ValidationCase(
        "the matrix structure with a comparator that cannot read dense records",
        builder ->
            builder
                .indexType(IndexType.MATRIX.getParamValue())
                .comparatorType(ComparatorType.JACCARD.getParamValue()),
        false),
    new ValidationCase(
        "the matrix structure with a comparator that can",
        builder ->
            builder
                .indexType(IndexType.MATRIX.getParamValue())
                .comparatorType(ComparatorType.L2.getParamValue()),
        true),
  };

  @Test
  void validationCases() {
    for (ValidationCase testCase : VALIDATION_CASES) {
      List<String> violations = violations(testCase.build(validBuilder()));
      assertEquals(testCase.valid, violations.isEmpty(), testCase.name);
    }
  }

  @Test
  void aBlankIndexTypeIsReportedOnlyByTheConfigItself() {
    List<String> violations = violations(validBuilder().indexType("").build());

    assertEquals(List.of("indexType must be a non-blank string."), violations);
  }

  /**
   * An unresolvable index type is reported alone: the pairing and param rules have no structure to
   * ask about.
   */
  @Test
  void anUnsupportedIndexTypeNamesTheSupportedOnes() {
    NamespaceConfig config =
        validBuilder()
            .indexType("term")
            .indexParams(Map.of(ConfigKeys.MAX_FRACTION_IDS_PER_TERM, "0"))
            .build();

    List<String> violations = violations(config);

    assertEquals(
        List.of(
            "Unsupported indexType (term). Supported values: "
                + "scan, matrix, inverted_term, inverted_signature, inverted_hybrid."),
        violations);
  }

  /** Merge on a signature-keyed structure still requires a conjunction-scoring comparator. */
  @Test
  void mergeWithASequenceComparatorIsRejectedOnASignatureStructure() {
    NamespaceConfig config =
        validBuilder()
            .indexType(IndexType.INVERTED_SIGNATURE.getParamValue())
            .comparatorType(ComparatorType.NGLD.getParamValue())
            .comparatorParams(Map.of(ConfigKeys.SIGNATURE_GENERATOR, "icws"))
            .indexParams(Map.of(ConfigKeys.CANDIDATE_GENERATOR, sparsMerge()))
            .build();

    List<String> violations = violations(config);

    assertEquals(1, violations.size(), violations.toString());
    assertEquals(
        String.format(
            "%s=%s is not supported with comparatorType ngld.",
            ConfigKeys.CANDIDATE_GENERATOR, sparsMerge()),
        violations.get(0));
  }

  @Test
  void validateThrowsForTheMatrixStructureWithAComparatorThatCannotReadDenseRecords() {
    NamespaceConfig config =
        validBuilder()
            .indexType(IndexType.MATRIX.getParamValue())
            .comparatorType(ComparatorType.JACCARD.getParamValue())
            .build();
    assertThrows(
        IllegalArgumentException.class, () -> config.validate(IndexConfigValidator.getInstance()));
  }

  /** The config's own structural checks report it, so the generator-dependent rules are skipped. */
  @Test
  void anUnparseableCandidateGeneratorTypeIsLeftToTheStructuralChecks() {
    NamespaceConfig config =
        validBuilder()
            .indexParams(Map.of(ConfigKeys.CANDIDATE_GENERATOR, "uni_outward"))
            .build();

    List<String> structuralViolations = config.collectStructuralViolations();

    assertEquals(structuralViolations, violations(config));
    assertEquals(1, structuralViolations.size(), structuralViolations.toString());
  }

  /**
   * Every comparator rule here needs a comparator to ask, and the comparator validator already
   * reports both an unknown name and unbuildable params.
   */
  @Test
  void aComparatorThatCannotBeCreatedIsLeftToTheComparatorValidator() {
    NamespaceConfig unknownType =
        validBuilder()
            .indexType(IndexType.INVERTED_SIGNATURE.getParamValue())
            .comparatorType("cosine")
            .indexParams(Map.of(ConfigKeys.CANDIDATE_GENERATOR, sparsMerge()))
            .build();
    // Merging would be reported for jaccard on its own, so this pins the params.
    Map<String, String> unbuildableParams = Map.of(ConfigKeys.SIGNATURE_GENERATOR, "superhash");
    // The structure names the comparator it computes from the config alone, so pairing it with
    // anything else is reported whether or not that comparator could be built. Naming l2 leaves
    // the params as the only thing wrong.
    NamespaceConfig unbuildableOnMatrixStructure =
        validBuilder()
            .indexType(IndexType.MATRIX.getParamValue())
            .comparatorType(ComparatorType.L2.getParamValue())
            .comparatorParams(unbuildableParams)
            .build();
    NamespaceConfig unbuildableWithMerge =
        validBuilder()
            .indexType(IndexType.INVERTED_SIGNATURE.getParamValue())
            .comparatorParams(unbuildableParams)
            .indexParams(Map.of(ConfigKeys.CANDIDATE_GENERATOR, sparsMerge()))
            .build();

    assertEquals(List.of(), violations(unknownType), "unknown type");
    assertEquals(
        List.of(), violations(unbuildableOnMatrixStructure), "unbuildable on the matrix structure");
    assertEquals(List.of(), violations(unbuildableWithMerge), "unbuildable with merge");
  }

  @Test
  void anUnknownIndexParamKeyNamesTheRecognizedOnes() {
    List<String> violations =
        violations(validBuilder().indexParams(Map.of("candidate_generation", "spars")).build());

    assertEquals(
        List.of(
            "Unknown indexParams key (candidate_generation). Supported keys: "
                + "candidate_generator, max_fraction_ids_per_term, max_pre_filtering_rows_ratio, "
                + "metadata_filtering_strategy, popular_term_discard_scope."),
        violations);
  }

  /**
   * The matrix structure stores dense records and so shares a record type with every
   * order-agnostic comparator. What separates them is whether a dot product determines the
   * measure, which Jaccard's intersection over populated positions does not.
   */
  @Test
  void theMatrixStructureIsReportedForAComparatorItCannotScoreByDotProducts() {
    List<String> violations =
        violations(
            validBuilder()
                .indexType(IndexType.MATRIX.getParamValue())
                .comparatorType(ComparatorType.JACCARD.getParamValue())
                .build());

    assertEquals(
        List.of(
            "indexType matrix scores every row by one dot product, and comparatorType jaccard "
                + "does not derive its similarity from one."),
        violations);
  }

  @Test
  void theMatrixStructureIsValidWithTheComparatorItComputes() {
    NamespaceConfig config =
        validBuilder()
            .indexType(IndexType.MATRIX.getParamValue())
            .comparatorType(ComparatorType.L2.getParamValue())
            .comparatorNormalizerType("reciprocal")
            .build();

    assertEquals(List.of(), violations(config));
  }

  /** A key recognized here is one some layer reads, whatever structure the namespace names. */
  @Test
  void aKeyOnlyOneStructureReadsIsRecognizedForEveryStructure() {
    NamespaceConfig config =
        validBuilder()
            .indexType(IndexType.MATRIX.getParamValue())
            .comparatorType(ComparatorType.L2.getParamValue())
            .indexParams(Map.of(ConfigKeys.MAX_FRACTION_IDS_PER_TERM, "0.5"))
            .build();

    assertEquals(List.of(), violations(config));
  }

  private static NamespaceConfig.Builder validBuilder() {
    return NamespaceConfig.builder()
        .minTermsAndValuesLength(0)
        .maxTermsAndValuesLength(4)
        .maxCacheSize(10)
        .cacheType("scan")
        .indexType("inverted_term")
        .comparatorType("jaccard")
        .comparatorNormalizerType("identity")
        .maxNumSearchableStructures(3)
        .maxNumSimilarities(5);
  }

  private static List<String> violations(NamespaceConfig config) {
    return config.collectViolations(IndexConfigValidator.getInstance());
  }

  private static String sparsMerge() {
    return CandidateGeneratorType.SPARS_MERGE.getParamValue();
  }

  @FunctionalInterface
  private interface BuilderMutation {
    NamespaceConfig.Builder apply(NamespaceConfig.Builder builder);
  }

  private record ValidationCase(String name, BuilderMutation build, boolean valid) {
    NamespaceConfig build(NamespaceConfig.Builder builder) {
      return build.apply(builder).build();
    }
  }
}

package com.uber.ussi.searchablestructure.index;

import static com.uber.ussi.TestLongObjectMaps.longHashSet;
import static com.uber.ussi.TestLongObjectMaps.sortedKeys;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.fail;

import com.uber.ussi.entity.meta.MetaFilter;
import com.uber.ussi.searchablestructure.result.RowNumAndSimilarity;
import com.uber.ussi.searchablestructure.utils.metadata.MetadataFilteringStrategy;
import com.uber.ussi.searchablestructure.utils.metadata.PreFilteringResult;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

class MetadataFilteredSearchExecutorTest {
  private static final MetaFilter FILTER = new MetaFilter(Map.of("city", List.of("sf")));

  @Test
  void unfilteredSearchBypassesMetadataResolvers() {
    MetadataFilteredSearchExecutor executor =
        newExecutor(
            MetadataFilteringStrategy.AUTO,
            MetadataFilteringStrategy.IN_FILTERING,
            /* autoAttemptPreFiltering */ true,
            MetadataFilteringStrategy.POST_FILTERING,
            filter -> fail("pre-filtering should not run without a metadata filter"),
            (maxResults, filter) -> fail("post-filter expansion should not run"),
            (rowNum, filter) -> fail("metadata matcher should not run"));

    List<RowNumAndSimilarity> result =
        executor.search(
            MetaFilter.empty(),
            2,
            (metadataFilter, maxResults) -> {
              assertNull(metadataFilter);
              assertEquals(2, maxResults);
              return List.of(row(10), row(11));
            },
            (candidateRowNums, metadataFilter, maxResults) ->
                fail("candidate scorer should not run"));

    assertEquals(List.of(10L, 11L), rowNums(result));
    assertEquals(
        MetadataFilteringStrategy.IN_FILTERING,
        executor.getResolvedMetadataFilteringStrategyForLastSearch());
  }

  @Test
  void autoUsesPreFilteringWhenResolverSucceeds() {
    MetadataFilteredSearchExecutor executor =
        newExecutor(
            MetadataFilteringStrategy.AUTO,
            MetadataFilteringStrategy.POST_FILTERING,
            /* autoAttemptPreFiltering */ true,
            MetadataFilteringStrategy.POST_FILTERING,
            filter -> {
              assertSame(FILTER, filter);
              return PreFilteringResult.success(longHashSet(10, 12));
            },
            (maxResults, filter) -> fail("post-filter expansion should not run"),
            (rowNum, filter) -> fail("metadata matcher should not run"));

    List<RowNumAndSimilarity> result =
        executor.search(
            FILTER,
            1,
            (metadataFilter, maxResults) -> fail("all-rows scorer should not run"),
            (candidateRowNums, metadataFilter, maxResults) -> {
              assertEquals(List.of(10L, 12L), sortedKeys(candidateRowNums));
              assertNull(metadataFilter);
              assertEquals(1, maxResults);
              return List.of(row(12));
            });

    assertEquals(List.of(12L), rowNums(result));
    assertEquals(
        MetadataFilteringStrategy.PRE_FILTERING,
        executor.getResolvedMetadataFilteringStrategyForLastSearch());
  }

  @Test
  void autoCanResolveDirectlyToFallbackStrategy() {
    MetadataFilteredSearchExecutor executor =
        newExecutor(
            MetadataFilteringStrategy.AUTO,
            MetadataFilteringStrategy.IN_FILTERING,
            /* autoAttemptPreFiltering */ false,
            MetadataFilteringStrategy.IN_FILTERING,
            filter -> fail("pre-filtering should not run"),
            (maxResults, filter) -> fail("post-filter expansion should not run"),
            (rowNum, filter) -> fail("metadata matcher should not run"));

    List<RowNumAndSimilarity> result =
        executor.search(
            FILTER,
            2,
            (metadataFilter, maxResults) -> {
              assertSame(FILTER, metadataFilter);
              assertEquals(2, maxResults);
              return List.of(row(10), row(11));
            },
            (candidateRowNums, metadataFilter, maxResults) ->
                fail("candidate scorer should not run"));

    assertEquals(List.of(10L, 11L), rowNums(result));
    assertEquals(
        MetadataFilteringStrategy.IN_FILTERING,
        executor.getResolvedMetadataFilteringStrategyForLastSearch());
  }

  @Test
  void preFilteringFallsBackWhenResolverFails() {
    MetadataFilteredSearchExecutor executor =
        newExecutor(
            MetadataFilteringStrategy.PRE_FILTERING,
            MetadataFilteringStrategy.IN_FILTERING,
            /* autoAttemptPreFiltering */ true,
            MetadataFilteringStrategy.IN_FILTERING,
            filter -> PreFilteringResult.failure(),
            (maxResults, filter) -> fail("post-filter expansion should not run"),
            (rowNum, filter) -> fail("metadata matcher should not run"));

    List<RowNumAndSimilarity> result =
        executor.search(
            FILTER,
            2,
            (metadataFilter, maxResults) -> {
              assertSame(FILTER, metadataFilter);
              assertEquals(2, maxResults);
              return List.of(row(10));
            },
            (candidateRowNums, metadataFilter, maxResults) ->
                fail("candidate scorer should not run"));

    assertEquals(List.of(10L), rowNums(result));
    assertEquals(
        MetadataFilteringStrategy.IN_FILTERING,
        executor.getResolvedMetadataFilteringStrategyForLastSearch());
  }

  @Test
  void postFilteringExpandsSearchAndKeepsBestMatchingRows() {
    MetadataFilteredSearchExecutor executor =
        newExecutor(
            MetadataFilteringStrategy.POST_FILTERING,
            MetadataFilteringStrategy.POST_FILTERING,
            /* autoAttemptPreFiltering */ false,
            MetadataFilteringStrategy.POST_FILTERING,
            filter -> fail("pre-filtering should not run"),
            (maxResults, filter) -> {
              assertEquals(1, maxResults);
              assertSame(FILTER, filter);
              return 3;
            },
            (rowNum, filter) -> {
              assertSame(FILTER, filter);
              return rowNum != 10;
            });

    List<RowNumAndSimilarity> result =
        executor.search(
            FILTER,
            1,
            (metadataFilter, maxResults) -> {
              assertNull(metadataFilter);
              assertEquals(3, maxResults);
              return List.of(row(10), row(11), row(12));
            },
            (candidateRowNums, metadataFilter, maxResults) ->
                fail("candidate scorer should not run"));

    assertEquals(List.of(12L), rowNums(result));
    assertEquals(
        MetadataFilteringStrategy.POST_FILTERING,
        executor.getResolvedMetadataFilteringStrategyForLastSearch());
  }

  @Test
  void postFilteringReturnsEmptyWhenExpansionIsZero() {
    MetadataFilteredSearchExecutor executor =
        newExecutor(
            MetadataFilteringStrategy.POST_FILTERING,
            MetadataFilteringStrategy.POST_FILTERING,
            /* autoAttemptPreFiltering */ false,
            MetadataFilteringStrategy.POST_FILTERING,
            filter -> fail("pre-filtering should not run"),
            (maxResults, filter) -> 0,
            (rowNum, filter) -> fail("metadata matcher should not run"));

    List<RowNumAndSimilarity> result =
        executor.search(
            FILTER,
            1,
            (metadataFilter, maxResults) -> fail("all-rows scorer should not run"),
            (candidateRowNums, metadataFilter, maxResults) ->
                fail("candidate scorer should not run"));

    assertTrue(result.isEmpty());
    assertEquals(
        MetadataFilteringStrategy.POST_FILTERING,
        executor.getResolvedMetadataFilteringStrategyForLastSearch());
  }

  private static MetadataFilteredSearchExecutor newExecutor(
      MetadataFilteringStrategy configuredStrategy,
      MetadataFilteringStrategy resolvedStrategyForUnfilteredSearch,
      boolean autoAttemptPreFiltering,
      MetadataFilteringStrategy fallbackStrategyWhenPreFilteringUnavailable,
      MetadataFilteredSearchExecutor.PreFilteringResolver preFilteringResolver,
      MetadataFilteredSearchExecutor.PostFilteringMaxResultsResolver
          postFilteringMaxResultsResolver,
      MetadataFilteredSearchExecutor.MetadataMatcher metadataMatcher) {
    return new MetadataFilteredSearchExecutor(
        configuredStrategy,
        resolvedStrategyForUnfilteredSearch,
        autoAttemptPreFiltering,
        fallbackStrategyWhenPreFilteringUnavailable,
        preFilteringResolver,
        postFilteringMaxResultsResolver,
        metadataMatcher);
  }

  private static RowNumAndSimilarity row(long rowNum) {
    return new RowNumAndSimilarity(rowNum, rowNum / 100.0f);
  }

  private static List<Long> rowNums(List<RowNumAndSimilarity> rows) {
    return rows.stream().map(RowNumAndSimilarity::getRowNum).toList();
  }
}

package com.uber.ussi.searchablestructure.result;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

import com.uber.ussi.utils.BoundedSizeMaxHeap;
import org.junit.jupiter.api.Test;

class ResultHeapsTest {

  @Test
  void newTopResultsUsesNearestFirstOrdering() {
    BoundedSizeMaxHeap<RowNumAndSimilarity> heap = ResultHeaps.newTopResults(2);
    heap.add(new RowNumAndSimilarity(1, 0.8f));
    heap.add(new RowNumAndSimilarity(2, 0.5f));
    heap.add(new RowNumAndSimilarity(3, 0.9f));

    assertEquals(2, heap.size());
    assertFalse(heap.toList().stream().anyMatch(result -> result.getRowNum() == 2));
  }

  @Test
  void conservativeMinSimilaritySitsOneStepBelowTheWeakestKeptResult() {
    BoundedSizeMaxHeap<RowNumAndSimilarity> heap = ResultHeaps.newTopResults(2);
    heap.add(new RowNumAndSimilarity(1, 0.8f));
    heap.add(new RowNumAndSimilarity(2, 0.5f));

    assertEquals(Math.nextDown(0.5f), ResultHeaps.getConservativeMinSimilarity(heap));
  }

  @Test
  void raisesTheMinimumSimilarityOnlyOnceTheHeapIsFull() {
    BoundedSizeMaxHeap<RowNumAndSimilarity> rows = ResultHeaps.newTopResults(2);

    assertEquals(
        0.3f,
        ResultHeaps.tightenedMinSimilarity(rows, 0.3f),
        "an empty heap has proved nothing");

    rows.add(new RowNumAndSimilarity(1, 0.9f));
    assertEquals(
        0.3f,
        ResultHeaps.tightenedMinSimilarity(rows, 0.3f),
        "a heap short of the rows the search keeps has proved nothing");

    rows.add(new RowNumAndSimilarity(2, 0.8f));
    assertEquals(
        Math.nextDown(0.8f),
        ResultHeaps.tightenedMinSimilarity(rows, 0.3f),
        "a full heap proves its weakest kept score");

    rows.add(new RowNumAndSimilarity(3, 0.95f));
    assertEquals(
        Math.nextDown(0.9f),
        ResultHeaps.tightenedMinSimilarity(rows, 0.3f),
        "and proves more as its weakest kept score rises");

    assertEquals(
        0.99f,
        ResultHeaps.tightenedMinSimilarity(rows, 0.99f),
        "the search's own minimum stands when it is the higher of the two");
  }
}

package com.uber.ussi.searchablestructure.index;

