package com.uber.ussi.searchablestructure.cache;

import com.uber.ussi.config.ConfigVocabulary;
import com.uber.ussi.config.NamespaceConfig;
import com.uber.ussi.error.CacheCreationError;
import java.util.Objects;

/** Factory for the ERD cache new(config) API. */
public final class CacheFactory {

  private CacheFactory() {}

  public static Cache createCache(NamespaceConfig namespaceConfig) {
    Objects.requireNonNull(namespaceConfig, "namespaceConfig");

    String configuredCacheType = namespaceConfig.getCacheType();
    CacheType cacheType = ConfigVocabulary.fromParamValue(CacheType.class, configuredCacheType);
    if (cacheType == null) {
      throw new CacheCreationError(
          ConfigVocabulary.unsupported("cacheType", configuredCacheType, CacheType.class));
    }
    return switch (cacheType) {
      case SCAN -> new ScanCache(namespaceConfig);
      case INVERTED_TERM -> new InvertedTermCache(namespaceConfig);
    };
  }
}

package com.uber.ussi.searchablestructure.utils.inverted;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

import java.util.Arrays;
import org.junit.jupiter.api.Test;

class KeyAndPrefixFilteringDataTest {

  @Test
  void sortingOrdersByNumRowsThenByDescendingContribution() {
    KeyAndPrefixFilteringData lowFrequency = new KeyAndPrefixFilteringData(2, 1, 1.0);
    KeyAndPrefixFilteringData highContribution = new KeyAndPrefixFilteringData(3, 2, 2.0);
    KeyAndPrefixFilteringData lowContribution = new KeyAndPrefixFilteringData(1, 2, 1.0);
    KeyAndPrefixFilteringData[] data = {lowContribution, highContribution, lowFrequency};

    Arrays.sort(data);

    assertSame(lowFrequency, data[0]);
    assertSame(highContribution, data[1]);
    assertSame(lowContribution, data[2]);
  }

  @Test
  void accessorsReturnTheKeyItsRowCountAndItsContribution() {
    KeyAndPrefixFilteringData data = new KeyAndPrefixFilteringData(2, 1, 1.0);

    assertEquals(2, data.getKey());
    assertEquals(1, data.getNumRows());
    assertEquals(1.0, data.getUniTransformedValue());
  }
}

package com.uber.ussi.searchablestructure.index.inverted;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.Arrays;
import org.junit.jupiter.api.Test;

class RowNumAndUniValueTest {

  private static final OrderingCase[] ORDERING_CASES = {
    new OrderingCase(
        new RowNumAndUniValue[] {
          new RowNumAndUniValue(2, 2.0),
          new RowNumAndUniValue(1, 1.0),
          new RowNumAndUniValue(3, 2.0)
        },
        new long[] {1, 2, 3}),
    new OrderingCase(
        new RowNumAndUniValue[] {
          new RowNumAndUniValue(5, 1.0, 0.25f), new RowNumAndUniValue(2, 1.0, 0.75f)
        },
        new long[] {2, 5}),
  };

  @Test
  void sortingOrdersByUniValueThenRowNum() {
    for (OrderingCase testCase : ORDERING_CASES) {
      RowNumAndUniValue[] entries = testCase.entries.clone();
      Arrays.sort(entries);
      long[] rowNums = new long[entries.length];
      for (int index = 0; index < entries.length; ++index) {
        rowNums[index] = entries[index].getRowNum();
      }
      assertArrayEquals(testCase.expectedRowOrder, rowNums, testCase.label());
    }
  }

  @Test
  void valueTravelsWithTheRowThroughSorting() {
    RowNumAndUniValue[] entries = {
      new RowNumAndUniValue(2, 2.0, 0.25f), new RowNumAndUniValue(1, 1.0, 0.75f)
    };
    Arrays.sort(entries);
    assertEquals(0.75f, entries[0].getValue());
    assertEquals(0.25f, entries[1].getValue());
  }

  private record OrderingCase(RowNumAndUniValue[] entries, long[] expectedRowOrder) {
    String label() {
      return Arrays.toString(expectedRowOrder);
    }
  }
}

package com.uber.ussi.searchablestructure.utils.parallel;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import org.junit.jupiter.api.Test;

class SharedMinSimilarityTest {

  @Test
  void holdsWhatItWasGivenUntilAHigherOneIsPublished() {
    SharedMinSimilarity minSimilarity = new SharedMinSimilarity(0.25f);

    assertEquals(0.25f, minSimilarity.get());

    minSimilarity.raiseTo(0.1f);
    assertEquals(0.25f, minSimilarity.get(), "a lower one is ignored");

    minSimilarity.raiseTo(0.25f);
    assertEquals(0.25f, minSimilarity.get(), "an equal one is ignored");

    minSimilarity.raiseTo(0.75f);
    assertEquals(0.75f, minSimilarity.get(), "a higher one is published");
  }

  @Test
  void keepsTheHighestWhenEveryShardPublishesAtOnce() throws Exception {
    int numShards = 16;
    SharedMinSimilarity minSimilarity = new SharedMinSimilarity(0.0f);
    CountDownLatch publishTogether = new CountDownLatch(1);
    List<Thread> shards = new ArrayList<>(numShards);
    for (int shard = 0; shard < numShards; shard++) {
      // Published lowest last, so taking the last write rather than the highest would end up
      // holding a low one.
      float published = (numShards - shard) / (float) numShards;
      shards.add(
          new Thread(
              () -> {
                try {
                  publishTogether.await();
                } catch (InterruptedException e) {
                  Thread.currentThread().interrupt();
                  return;
                }
                minSimilarity.raiseTo(published);
              }));
    }
    shards.forEach(Thread::start);

    publishTogether.countDown();
    for (Thread shard : shards) {
      shard.join();
    }

    assertEquals(1.0f, minSimilarity.get());
  }
}

